import React, { useEffect } from 'react';
import { BrowserRouter as Router, Route, Routes } from 'react-router-dom';
import Home from './pages/Home';
import SimilarTracks from './pages/SimilarTracks';
import Login from './components/Login';
import { getTokenFromUrl, setAccessToken } from './services/api';

function App() {
  useEffect(() => {
    // Check for access token in URL
    const hash = getTokenFromUrl();
    const token = hash.access_token;
    if (token) {
      setAccessToken(token);
      window.location.hash = ''; // Remove token from URL
    }
  }, []);

  return (
    <Router>
      <div>
        <h1>Track Similarity App</h1>
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/login" element={<Login />} />
          <Route path="/similar-tracks" element={<SimilarTracks />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
